SELECT 1
FROM med_appointment
WHERE patient_id = #{patientId}
  AND slot_id = #{slotId}
  AND active_flag = 1
LIMIT 1

SELECT 
FROM med_appointment appointment
INNER JOIN med_patient patient ON patient.id = appointment.patient_id
WHERE patient.id = #{patientId}
  AND patient.owner_user_id = #{ownerUserId}

ORDER BY appointment.created_at DESC, appointment.id DESC
LIMIT #{limit}

SELECT 
FROM med_appointment appointment
INNER JOIN med_patient patient ON patient.id = appointment.patient_id
WHERE patient.owner_user_id = #{ownerUserId}

ORDER BY appointment.created_at DESC, appointment.id DESC
LIMIT #{limit}

SELECT id, confirm_deadline FROM med_appointment WHERE status = 'PENDING_CONFIRMATION' AND confirm_deadline <= CURRENT_TIMESTAMP(3)
AND (confirm_deadline > #{afterDeadline} OR (confirm_deadline = #{afterDeadline} AND id > #{afterId}))
ORDER BY confirm_deadline ASC, id ASC LIMIT #{limit}
